"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["68196"],{19637(e,t,o){o.d(t,{Ay:()=>a,RM:()=>s});var n=o(74848),i=o(28453);let s=[];function l(e){let t={blockquote:"blockquote",h1:"h1",header:"header",p:"p",...(0,i.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t.header,{children:(0,n.jsx)(t.h1,{id:"to-hell-with-the-bulls-who-wanted-to-pull-a-big-rally-today",children:"To Hell with the Bulls Who Wanted to Pull a Big Rally Today"})}),"\n",(0,n.jsxs)(t.blockquote,{children:["\n",(0,n.jsx)(t.p,{children:"2007/10/22 15:25:35"}),"\n"]}),"\n",(0,n.jsx)("div",{style:{color:"#FF0000",fontWeight:"500",fontSize:"56px",lineHeight:"150%"},children:(0,n.jsx)(t.p,{children:"First, with the warmest applause, let us congratulate the stock market for becoming thoroughly Peking University-fied from here on."})}),"\n",(0,n.jsxs)("div",{style:{color:"#009900",fontWeight:"500",fontSize:"18px"},children:[(0,n.jsx)(t.p,{children:"I heard the bulls wanted to pull a big rally today, just like last time when some bears said September 20th was a time window \u2014 this ID just loves making these people lose face. The world has become very Peking University-fied, the consequences are Peking University-fied, and this ID is happy-ing."}),(0,n.jsx)(t.p,{children:"But this ID has nothing more to say \u2014 the feeling of having everything under control always leaves nothing to say. For the bears, the most beautiful applause right now is the cursing from the bulls \u2014 this must be the most melodious music in the world."}),(0,n.jsx)(t.p,{children:"The 1-minute downtrend that began from such an exquisite point of 6124.04, continues with hubs shifting ever lower. Right now it has closed exactly on the lower rail of the ascending channel from 3600 points, and that gap at 5600 points is right before our eyes. Once this level is effectively broken, the correction targeting the rally from 3600 points will be confirmed."}),(0,n.jsx)(t.p,{children:"Those with good technique can closely watch for the bottom divergence in the 1-minute downtrend from 6124.04 \u2014 then there will be a rebound to trade. Those without the skill, forget it \u2014 if you don't have the ability, just continue sitting on your little stool watching the show."}),(0,n.jsx)(t.p,{children:"Being a bear means making money even during declines \u2014 that's what a true bear is. Buy at the bottom divergence, then dump on the way up \u2014 that's a rather exhilarating game. The key question is: do you have the potential for such exhilaration? If your portfolio value today is less than on the day of 6124.04, you'd better seriously reflect on your potential."}),(0,n.jsx)(t.p,{children:"As for those without technique, if your portfolio value today is less than on the day of 6124.04, wait for an opportunity to exit. Though it's a bit late, this is the consequence of not correctly understanding yourself. If you get a chance to return to your portfolio value on the day of 6124.04, get out of some positions first \u2014 this way you still have a chance to be among that less-than-20%."}),(0,n.jsx)(t.p,{children:"Note: we are now entering a policy-sensitive period. Though the probability favors the bears, a new official has just taken office and nobody can yet get a read on their style. This ID currently has no interest in the market \u2014 just like when this ID bought China National Aviation when it dropped below IPO price and called on everyone to buy, this ID actually had zero interest in China National Aviation, only interest in Mr. Li Jun."}),(0,n.jsx)(t.p,{children:"After the 1-minute decline ends, there is a very high probability of entering a box pattern \u2014 a pattern suitable for sucking blood both up and down \u2014 then waiting for policy to complete the breakout. Right now this ID also really wants to know: in a certain gentleman's mind, does 5000 points count as high, and is there a bubble? If anyone knows, please tell this ID."}),(0,n.jsx)(t.p,{children:"Meetings all afternoon and evening, signing off first, see you later."})]})]})}function a(e={}){let{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,n.jsx)(t,{...e,children:(0,n.jsx)(l,{...e})}):l(e)}},20103(e,t,o){o.r(t),o.d(t,{metadata:()=>n,default:()=>d,frontMatter:()=>a,contentTitle:()=>r,toc:()=>u,assets:()=>h});var n=JSON.parse('{"id":"stocks/longbuyerstohell","title":"","description":"","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/stocks/longbuyerstohell.md","sourceDirName":"stocks","slug":"/stocks/longbuyerstohell","permalink":"/en/stocks/longbuyerstohell","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"longbuyerstohell","title":"","hide_table_of_contents":true,"sidebar_label":"Let the bulls who wanted to pull a big bullish candle today go to hell (2007/10/22 15:25:35)"},"sidebar":"stocksExtendedSidebar","previous":{"title":"Beijing Travel Guide 3: Autumn Red Leaves in the Capital (2007/10/21 15:58:08)","permalink":"/en/stocks/beijingtravelguide3"},"next":{"title":"Teaching You Stock Trading 85: Some Anecdotes of Toying with Market Makers 3 (2007/10/22 21:42:06)","permalink":"/en/stocks/085"}}'),i=o(74848),s=o(28453),l=o(19637);let a={id:"longbuyerstohell",title:"",hide_table_of_contents:!0,sidebar_label:"Let the bulls who wanted to pull a big bullish candle today go to hell (2007/10/22 15:25:35)"},r,h={},u=[...l.RM];function c(e){return(0,i.jsx)(l.Ay,{})}function d(e={}){let{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(c,{...e})}):c(e)}},28453(e,t,o){o.d(t,{R:()=>l,x:()=>a});var n=o(96540);let i={},s=n.createContext(i);function l(e){let t=n.useContext(s);return n.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function a(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:l(e.components),n.createElement(s.Provider,{value:t},e.children)}}}]);